import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../core/database/app_database.dart';
import '../defects/defects_page.dart';
class InspectionsPage extends StatefulWidget{const InspectionsPage({super.key});@override State<InspectionsPage> createState()=>_InspectionsPageState();}
class _InspectionsPageState extends State<InspectionsPage>{List<Map<String,dynamic>> rows=[],buildings=[];@override void initState(){super.initState();load();}Future<void> load()async{rows=await AppDatabase.instance.query('inspections',order:'date DESC');buildings=await AppDatabase.instance.query('buildings');if(mounted)setState((){});}Future<void> start()async{if(buildings.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أضف مبنى أولًا')));return;}String bid='${buildings.first['id']}';final e=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(dialogContext)=>StatefulBuilder(builder:(context,setDialogState)=>AlertDialog(title:const Text('بدء معاينة'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:bid,items:buildings.map((b)=>DropdownMenuItem<String>(value:'${b['id']}',child:Text('${b['name']}'))).toList(),onChanged:(v)=>setDialogState(()=>bid=v??bid)),TextField(controller:e,decoration:const InputDecoration(labelText:'اسم المهندس'))]),actions:[TextButton(onPressed:()=>Navigator.pop(dialogContext,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(dialogContext,true),child:const Text('بدء'))])));if(ok==true&&e.text.trim().isNotEmpty){await AppDatabase.instance.insert('inspections',{'id':const Uuid().v4(),'buildingId':bid,'engineer':e.text.trim(),'date':DateTime.now().toIso8601String(),'status':'نشطة','notes':''});await load();}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المعاينات')),floatingActionButton:FloatingActionButton.extended(onPressed:start,icon:const Icon(Icons.play_arrow),label:const Text('بدء')),body:ListView(padding:const EdgeInsets.all(16),children:rows.map((x)=>Card(child:ListTile(title:Text('معاينة ${'${x['date']}'.substring(0,10)}'),subtitle:Text('المهندس: ${x['engineer']}'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DefectsPage(inspection:x))))).toList()));}
class BuildingInspectionPage extends StatelessWidget{final Map<String,dynamic> building;const BuildingInspectionPage({super.key,required this.building});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('${building['name']}')),body:const Center(child:Text('يمكن بدء معاينة هذا المبنى من تبويب المعاينة الميدانية.')));}
